func (this *Coinmate) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"FILLED":           "closed",
		"CANCELLED":        "canceled",
		"PARTIALLY_FILLED": "open",
		"OPEN":             "open",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Coinmate) ParseOrderType(typeVar *string) *string {
	var types map[string]any = map[string]any{
		"LIMIT":  "limit",
		"MARKET": "market",
	}
	return this.SafeString(types, typeVar, typeVar)
}
func (this *Coinmate) ParseOrder(order any, optionalArgs ...any) Order {
	//
	// limit sell
	//
	//     {
	//         "id": 781246605,
	//         "timestamp": 1584480015133,
	//         "trailingUpdatedTimestamp": null,
	//         "type": "SELL",
	//         "currencyPair": "ETH_BTC",
	//         "price": 0.0345,
	//         "amount": 0.01,
	//         "stopPrice": null,
	//         "originalStopPrice": null,
	//         "marketPriceAtLastUpdate": null,
	//         "marketPriceAtOrderCreation": null,
	//         "orderTradeType": "LIMIT",
	//         "hidden": false,
	//         "trailing": false,
	//         "clientOrderId": null
	//     }
	//
	// limit buy
	//
	//     {
	//         "id": 67527001,
	//         "timestamp": 1517931722613,
	//         "trailingUpdatedTimestamp": null,
	//         "type": "BUY",
	//         "price": 5897.24,
	//         "remainingAmount": 0.002367,
	//         "originalAmount": 0.1,
	//         "stopPrice": null,
	//         "originalStopPrice": null,
	//         "marketPriceAtLastUpdate": null,
	//         "marketPriceAtOrderCreation": null,
	//         "status": "CANCELLED",
	//         "orderTradeType": "LIMIT",
	//         "hidden": false,
	//         "avgPrice": null,
	//         "trailing": false,
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "success": true,
	//        "remainingAmount": 0.1
	//    }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "id")
	var timestamp *int64 = this.SafeInteger(order, "timestamp")
	var side *string = this.SafeStringLower(order, "type")
	var priceString *string = this.SafeString(order, "price")
	var amountString *string = this.SafeString(order, "originalAmount")
	var remainingString *string = this.SafeString2(order, "remainingAmount", "amount")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	var typeVar *string = this.ParseOrderType(this.SafeString(order, "orderTradeType"))
	var averageString *string = this.SafeString(order, "avgPrice")
	var marketId *string = this.SafeString(order, "currencyPair")
	var symbol *string = this.SafeSymbol(marketId, market, "_")
	var clientOrderId *string = this.SafeString(order, "clientOrderId")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      clientOrderId,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"symbol":             symbol,
		"type":               typeVar,
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              priceString,
		"triggerPrice":       this.SafeNumber(order, "stopPrice"),
		"amount":             amountString,
		"cost":               nil,
		"average":            averageString,
		"filled":             nil,
		"remaining":          remainingString,
		"status":             status,
		"trades":             nil,
		"info":               order,
		"fee":                nil,
	}, market)
}

/**
 * @method
 * @name coinmate#createOrder
 * @description create a trade order
 * @see https://coinmate.docs.apiary.io/#reference/order/buy-limit-order/post
 * @see https://coinmate.docs.apiary.io/#reference/order/sell-limit-order/post
 * @see https://coinmate.docs.apiary.io/#reference/order/buy-instant-order/post
 * @see https://coinmate.docs.apiary.io/#reference/order/sell-instant-order/post
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Coinmate) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Coinmate) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var method string = "privatePost" + this.Capitalize(side)
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"currencyPair": market["id"],
	}
	if typeVar == "market" {
		if side == "buy" {
			request["total"] = this.AmountToPrecision(symbol, amount) // amount in fiat
		} else {
			request["amount"] = this.AmountToPrecision(symbol, amount) // amount in fiat
		}
		method += "Instant"
	} else {
		request["amount"] = this.AmountToPrecision(symbol, amount) // amount in crypto
		request["price"] = this.PriceToPrecision(symbol, price)
		method += this.Capitalize(typeVar)
	}
	var requestParams map[string]any = this.Extend(request, params)
	var response map[string]any = nil
	if method == "privatePostBuyInstant" {

		r1 := <-this.PrivatePostBuyInstant(requestParams)
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else if method == "privatePostSellInstant" {

		r2 := <-this.PrivatePostSellInstant(requestParams)
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	} else if method == "privatePostBuyLimit" {

		r3 := <-this.PrivatePostBuyLimit(requestParams)
		if r3.Err != nil {
			panic(r3.Err)
		}
		response = r3.Value
	} else if method == "privatePostSellLimit" {

		r4 := <-this.PrivatePostSellLimit(requestParams)
		if r4.Err != nil {
			panic(r4.Err)
		}
		response = r4.Value
	} else {
		panic(InvalidOrder(this.Id + " createOrder() does not support order type " + typeVar))
	}
	var id *string = this.SafeString(response, "data")

	ch <- AsyncResult[Order]{Value: this.SafeOrder(map[string]any{
		"info": response,
		"id":   id,
	}, market)}
	return nil
}

